                Inner.EncodeInto(msg.SetMessage("inner"));
            }
            if (Nums.Count != 0) {
                foreach (var v in Nums) { msg.Set("nums", (long)v); }
            }
            if (Tags.Count != 0) {
                foreach (var v in Tags) { msg.Set("tags", v); }
            }
            if (Inners.Count != 0) {
                foreach (var v in Inners) { v.EncodeInto(msg.SetMessage("inners")); }
            }
            if (HasOptI32) {
                msg.Set("opt_i32", (long)OptI32);
            }
            if (HasOptStr) {
                msg.Set("opt_str", OptStr);
            }
            if (Flags.Count != 0) {
                foreach (var v in Flags) { msg.Set("flags", v); }
            }
        }
        internal void LoadFrom(Pbwire.Message msg) {
            I32 = (int)msg.GetInt("i32");
            I64 = msg.GetLong("i64");
            U32 = (uint)msg.GetInt("u32");
            U64 = unchecked((ulong)msg.GetLong("u64"));
            S32 = (int)msg.GetInt("s32");
            S64 = msg.GetLong("s64");
            Fx32 = (uint)msg.GetInt("fx32");
            Fx64 = unchecked((ulong)msg.GetLong("fx64"));
            Sfx32 = (int)msg.GetInt("sfx32");
            Sfx64 = msg.GetLong("sfx64");
            F32 = msg.GetFloat("f32");
            F64 = msg.GetDouble("f64");
            Flag = msg.GetBool("flag");
            Str = msg.GetString("str") ?? "";
            Color = (Color3)msg.GetInt("color");
            var subInner = msg.GetMessage("inner");
            if (subInner != null) { Inner = new Inner3(); Inner.LoadFrom(subInner); }
            for (int i = 0; i < msg.Count("nums"); i++) {
                var itemNums = msg.At("nums", i);
                if (itemNums != null) { Nums.Add((int)itemNums.AsInt()); }
            }
            for (int i = 0; i < msg.Count("tags"); i++) {
                var itemTags = msg.At("tags", i);
                if (itemTags != null) { Tags.Add(itemTags.AsString() ?? ""); }
            }
            for (int i = 0; i < msg.Count("inners"); i++) {
                var item = msg.At("inners", i);
                var sub = item?.AsMessage();
                if (sub != null) { var m = new Inner3(); m.LoadFrom(sub); Inners.Add(m); }
            }
            if (msg.Has("opt_i32")) { OptI32 = (int)msg.GetInt("opt_i32"); }
            if (msg.Has("opt_str")) { OptStr = msg.GetString("opt_str") ?? ""; }
            for (int i = 0; i < msg.Count("flags"); i++) {
                var itemFlags = msg.At("flags", i);
                if (itemFlags != null) { Flags.Add(itemFlags.AsBool()); }
            }
        }
    }

